func gtPage(grl *port.Cells, gfl *port.Cells, ggp *port.Cells, grg *port.Cells, refs *port.Cells, page int32) int32 {
	// One page: a group of one vector member (the path 7, its first point 3), two rules in it, a fill in it, and a region.
	var g int32 = 0
	var r int32 = 0
	port.CellsDrop(grl, 0)
	port.CellsDrop(gfl, 0)
	port.CellsDrop(ggp, 0)
	port.CellsDrop(grg, 0)
	port.CellsDrop(refs, 0)
	evidence.RfAdd(refs, evidence.EaPaths(), 7)
	evidence.RfAdd(refs, evidence.EaPts(), 3)
	g = glayer.GgpNew(ggp, page, glayer.GkRule())
	glayer.GgpSet(ggp, g, 2, 0)
	glayer.GgpSet(ggp, g, 3, 2)
	r = glayer.GrlNew(grl, page, 1000, 4950, 21000, 5050, 1000, 5000, 21000, 5000, 100, glayer.GoH())
	glayer.GrlSet(grl, r, 14, glayer.GsVector())
	glayer.GrlSet(grl, r, 15, glayer.GsVector())
	glayer.GrlSet(grl, r, 16, 501)
	glayer.GrlSet(grl, r, 17, 900)
	glayer.GrlSet(grl, r, 12, 0)
	glayer.GrlSet(grl, r, 19, g)
	r = glayer.GrlNew(grl, page, 1000, 5000, 1100, 8000, 1050, 5000, 1050, 8000, 100, glayer.GoV())
	glayer.GrlSet(grl, r, 18, glayer.GqBoxEdge())
	glayer.GrlSet(grl, r, 19, g)
	r = glayer.GflNew(gfl, page, 2000, 2000, 9000, 3000, 16711680)
	glayer.GflSet(gfl, r, 6, 299)
	glayer.GflSet(gfl, r, 11, glayer.GqfShading())
	glayer.GflSet(gfl, r, 12, g)
	r = glayer.GrgNew(grg, page, 0, 0, 30000, 40000, glayer.RkTableInImage())
	glayer.GrgSet(grg, r, 7, 13)
	glayer.GrgSet(grg, r, 8, 4)
	glayer.GrgSet(grg, r, 9, 2)
	glayer.GrgSet(grg, r, 10, 1)
	return 0
}

func TestAHandBuiltLayerIsSound(emonT *testing.T) {
	var grl *port.Cells = port.NewCells()
	var gfl *port.Cells = port.NewCells()
	var ggp *port.Cells = port.NewCells()
	var grg *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	gtPage(grl, gfl, ggp, grg, refs, 1)
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 0, "sound")
	port.AssertEq(emonT, glayer.GrlCount(grl), 2, "two rules")
	port.AssertEq(emonT, glayer.GflCount(gfl), 1, "one fill")
	port.AssertEq(emonT, glayer.GgpGet(ggp, 0, 4), -1, "an absent run is first -1")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 12), 0, "a colour set")
	port.AssertEq(emonT, glayer.GrlGet(grl, 1, 12), -1, "a colour not set is -1")
	port.AssertEq(emonT, glayer.GrlGet(grl, 1, 20), -1, "no z")
}

func TestTheCheckerNoticesEveryWayOfBeingBroken(emonT *testing.T) {
	var grl *port.Cells = port.NewCells()
	var gfl *port.Cells = port.NewCells()
	var ggp *port.Cells = port.NewCells()
	var grg *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	gtPage(grl, gfl, ggp, grg, refs, 1)
	port.CellsPush(grl, 0)
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 1, "a stride")
	port.CellsDrop(grl, 48)
	glayer.GrlSet(grl, 1, 19, 5)
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 2, "a rule's group outside ggp")
	glayer.GrlSet(grl, 1, 19, 0)
	glayer.GflSet(gfl, 0, 12, 3)
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 2, "a fill's group outside ggp")
	glayer.GflSet(gfl, 0, 12, 0)
	glayer.GgpSet(ggp, 0, 3, 9)
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 3, "a member run outside refs")
	glayer.GgpSet(ggp, 0, 3, 2)
	glayer.GrlSet(grl, 0, 10, 4)
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 4, "an orientation outside go")
	glayer.GrlSet(grl, 0, 10, 1)
	glayer.GrlSet(grl, 0, 9, -1)
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 4, "a negative thickness")
	glayer.GrlSet(grl, 0, 9, 100)
	glayer.GrlSet(grl, 0, 1, 99999)
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 4, "a box upside down")
	glayer.GrlSet(grl, 0, 1, 1000)
	glayer.GrgSet(grg, 0, 5, 9)
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 5, "a region of an unknown kind")
	glayer.GrgSet(grg, 0, 5, 1)
	glayer.GrgSet(grg, 0, 8, -1)
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 5, "a half subject")
	glayer.GrgSet(grg, 0, 8, 4)
	evidence.RfAdd(refs, 41, 9)
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 6, "a reference into a rule that is not there")
	port.CellsDrop(refs, 4)
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 0, "sound again")
}

func TestTwoPagesAppendAndRebase(emonT *testing.T) {
	var grl *port.Cells = port.NewCells()
	var gfl *port.Cells = port.NewCells()
	var ggp *port.Cells = port.NewCells()
	var grg *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	var pgrl *port.Cells = port.NewCells()
	var pgfl *port.Cells = port.NewCells()
	var pggp *port.Cells = port.NewCells()
	var pgrg *port.Cells = port.NewCells()
	var prefs *port.Cells = port.NewCells()
	gtPage(pgrl, pgfl, pggp, pgrg, prefs, 1)
	glayer.GlAppend(grl, gfl, ggp, grg, pgrl, pgfl, pggp, pgrg, 0)
	evidence.RfAdd(refs, evidence.EaPaths(), 7)
	evidence.RfAdd(refs, evidence.EaPts(), 3)
	gtPage(pgrl, pgfl, pggp, pgrg, prefs, 2)
	glayer.GlAppend(grl, gfl, ggp, grg, pgrl, pgfl, pggp, pgrg, 2)
	evidence.RfAdd(refs, evidence.EaPaths(), 7)
	evidence.RfAdd(refs, evidence.EaPts(), 3)
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 0, "two pages are sound")
	port.AssertEq(emonT, glayer.GrlCount(grl), 4, "rules")
	port.AssertEq(emonT, glayer.GflCount(gfl), 2, "fills")
	port.AssertEq(emonT, glayer.GgpCount(ggp), 2, "groups")
	port.AssertEq(emonT, glayer.GrgCount(grg), 2, "regions")
	port.AssertEq(emonT, glayer.GrlGet(grl, 2, 19), 1, "the second page's rule is in the document's second group")
	port.AssertEq(emonT, glayer.GflGet(gfl, 1, 12), 1, "and its fill")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 19), 0, "the first page's is not moved")
	port.AssertEq(emonT, glayer.GgpGet(ggp, 1, 2), 2, "the second group's member run starts after the first page's refs")
	port.AssertEq(emonT, glayer.GgpGet(ggp, 1, 4), -1, "an absent run stays absent")
	port.AssertEq(emonT, glayer.GrgGet(grg, 1, 7), 13, "a region's subject, an evidence row, is not re-based")
	port.AssertEq(emonT, glayer.GrgGet(grg, 1, 8), 4, "nor its index")
	port.AssertEq(emonT, glayer.GrlGet(grl, 3, 0), 2, "pages are kept")
}

func gtWidth(kind int32, arg int32) int32 {
	// How many cells a field of the dump table covers.
	if kind == 3 {
		return 4
	}
	if (kind == 4) || (kind == 5) {
		return 2
	}
	return 1
}

func TestEveryCellIsPrintedOrNamedSpare(emonT *testing.T) {
	// per arena of the field table: the cells its rows cover, plus its spare cells, are its stride, and no two rows overlap
	var a int32 = 0
	var k int32 = 0
	var covered int32 = 0
	var next int32 = 0
	var f int32 = 0
	for a < 4 {
		covered = 0
		next = 0
		k = 0
		for k < glayer.GlFx[a*4+1] {
			f = glayer.GlFd[(glayer.GlFx[a*4+0]+k)*6+1]
			port.AssertThat(emonT, f >= next, "the fields are in stride order and do not overlap")
			covered += gtWidth(glayer.GlFd[(glayer.GlFx[a*4+0]+k)*6+2], glayer.GlFd[(glayer.GlFx[a*4+0]+k)*6+5])
			next = f + gtWidth(glayer.GlFd[(glayer.GlFx[a*4+0]+k)*6+2], glayer.GlFd[(glayer.GlFx[a*4+0]+k)*6+5])
			k += 1
		}
		port.AssertEq(emonT, covered+glayer.GlFx[a*4+3], glayer.GlFx[a*4+2], "printed plus spare is the stride")
		a += 1
	}
	port.AssertEq(emonT, a, 4, "four arenas")
}

